const hash=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),b=>b.toString(16).padStart(2,'0')).join('');
class HttpError extends Error{constructor(status,message,code){super(message);this.status=status;this.code=code;}}
const fail=(status,message,code)=>{throw new HttpError(status,message,code);};
const json=(data,status=200,headers={})=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff',...headers}});
const stmt=(db,sql,...args)=>db.prepare(sql).bind(...args);
const run=(db,sql,...args)=>stmt(db,sql,...args).run();
const first=(db,sql,...args)=>stmt(db,sql,...args).first();
const all=async(db,sql,...args)=>(await stmt(db,sql,...args).all()).results;
const text=(v,min=0,max=500)=>{if(typeof v!=='string'||v.trim().length<min||v.length>max)fail(400,`Preencha os campos corretamente (até ${max} caracteres).`);return v.trim();};
const email=v=>{v=text(v,3,254).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))fail(400,'Informe um e-mail válido.');return v;};
const password=v=>{if(typeof v!=='string'||v.length<12||bcrypt.truncates(v))fail(400,'Use uma senha com pelo menos 12 caracteres e no máximo 72 bytes.');return v;};
const cleanUser=u=>({id:u.id,email:u.email,name:u.name,role:u.role,status:u.status,created:u.created});
const audit=(db,u,action,target)=>stmt(db,'INSERT INTO audit(id,actor,action,target,created) VALUES(?,?,?,?,?)',uid(),u.id,action,target,now());
