// Duração da aula: "HH:MM:SS" (ou "HH:MM") vinda do painel, guardada em segundos; minutos arredondados para cima por compatibilidade.
// durationSource 'panel' indica que a duração real foi informada e não deve ser trocada pela estimativa de uma reimportação.
function lessonDuration(b){
 if(b.durationTime!==undefined&&b.durationTime!==''){const m=/^(\d{1,2}):([0-5]\d)(?::([0-5]\d))?$/.exec(String(b.durationTime));if(!m)fail(400,'Informe a duração no formato HH:MM:SS.');const s=Number(m[1])*3600+Number(m[2])*60+Number(m[3]||0);if(s>12*3600)fail(400,'A duração máxima de uma aula é 12 horas.');return{durationSeconds:s,duration:Math.ceil(s/60),durationSource:'panel'};}
 const minutes=Math.max(0,Math.min(999,Number(b.duration)||0));return{duration:minutes,durationSeconds:minutes*60};
}
// Links de consulta da aula: aceita http e https (há sites públicos ainda sem https), nunca outros protocolos.
function linkValue(v){let u;try{u=new URL(String(v||'').trim());}catch{fail(400,'Informe um link válido, começando com https://.');}if(!['https:','http:'].includes(u.protocol)||u.username||u.password)fail(400,'Use um link http ou https sem credenciais.');return u.href;}
function urlValue(v){if(!v)return '';let u;try{u=new URL(v);}catch{fail(400,'Informe um endereço HTTPS válido.');}if(u.protocol!=='https:'||u.username||u.password)fail(400,'Use um endereço HTTPS sem credenciais.');return u.href;}
export function videoSource(value){const s=urlValue(value);if(!s)return null;const u=new URL(s),host=u.hostname.toLowerCase();if(['www.youtube.com','youtube.com','youtu.be','www.youtube-nocookie.com'].includes(host)){const id=host==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').pop();if(!/^[a-zA-Z0-9_-]{11}$/.test(id))fail(400,'Link do YouTube inválido.');return{type:'iframe',url:'https://www.youtube-nocookie.com/embed/'+id};}if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(host)){const id=u.pathname.split('/').filter(Boolean).pop();if(!/^\d+$/.test(id))fail(400,'Link do Vimeo inválido.');return{type:'iframe',url:'https://player.vimeo.com/video/'+id};}if(/\.mp4$/i.test(u.pathname))return{type:'video',url:s};fail(400,'Use um vídeo do YouTube, Vimeo ou um arquivo MP4 em HTTPS.');}
async function body(req){const raw=await req.text(),path=new URL(req.url).pathname,limit=path.startsWith('/api/planner/attachments')?2900000:path.startsWith('/api/admin/records')?850000:100000;if(raw.length>limit)fail(413,'Conteúdo muito grande.');try{return JSON.parse(raw);}catch{fail(400,'Dados inválidos.');}}
async function rate(db,key,max=12){const t=now();const row=await stmt(db,'INSERT INTO limits(key,count,until) VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN until<? THEN 1 ELSE count+1 END,until=CASE WHEN until<? THEN excluded.until ELSE until END RETURNING count',key,t+900,t,t).first();if(row.count>max)fail(429,'Muitas tentativas. Aguarde 15 minutos e tente novamente.');}
async function session(req,db){const raw=req.headers.get('cookie')||'';const value=raw.split(';').map(s=>s.trim()).find(s=>s.startsWith(cookieName+'='))?.slice(cookieName.length+1);if(!value||!/^[a-f0-9]{64}$/.test(value))return null;return first(db,'SELECT users.*,sessions.token AS session_token FROM sessions JOIN users ON users.id=sessions.user_id WHERE sessions.token=? AND sessions.expires>? AND users.status=?',await hash(value),now(),'active');}
async function loginResponse(db,u){const value=token();await db.batch([stmt(db,'DELETE FROM sessions WHERE expires<?',now()),stmt(db,'INSERT INTO sessions(token,user_id,expires) VALUES(?,?,?)',await hash(value),u.id,now()+86400)]);return json({user:cleanUser(u),access:await accessOf(db,u)},200,{'Set-Cookie':`${cookieName}=${value}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=86400`});}
const clientIp=req=>req.headers.get('x-arrivo-client-ip')||'unknown';
async function initializeCatalog(db){const statements=seed.map(r=>stmt(db,'INSERT OR IGNORE INTO records(id,kind,body,status,revision,updated) VALUES(?,?,?,?,1,?)',r.id,r.kind,JSON.stringify(r.body),r.status,now()));for(let i=0;i<statements.length;i+=30)await db.batch(statements.slice(i,i+30));for(const file of await catalogFiles())await importTrack(db,JSON.parse(await fs.readFile(file,'utf8')),nodePath.resolve('data','files'));}
// Acesso: o curso libera a plataforma por um período; Planner e Fornitore são extras que nunca passam da validade do curso.
const products=['course','planner','fornitore'];
const lockedMessage={course:'Seu acesso ao Arrivo In Itália não está ativo. Renove para continuar.',planner:'O Planner é um adicional que ainda não faz parte do seu acesso.',fornitore:'O Fornitore é um adicional que ainda não faz parte do seu acesso.'};
async function accessOf(db,u){
 if(u.role==='admin')return Object.fromEntries(products.map(p=>[p,{active:true,expires:null}]));
 const t=now(),rows=await all(db,"SELECT product,max(expires) AS expires FROM entitlements WHERE user_id=? AND status='active' AND starts<=? AND expires>? GROUP BY product",u.id,t,t);
 const current=Object.fromEntries(rows.map(r=>[r.product,r.expires])),course=current.course||null;
 const last=course?null:(await first(db,"SELECT max(expires) AS expires FROM entitlements WHERE user_id=? AND product='course' AND status='active'",u.id))?.expires||null;
 const access={course:{active:!!course,expires:course,expired:last}};
 for(const p of ['planner','fornitore']){const expires=course&&current[p]?Math.min(course,current[p]):null;access[p]={active:!!expires,expires};}
 return access;
}
// Validade informada como data (AAAA-MM-DD) vale até o fim do dia no horário de Brasília.
function endOfDay(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))fail(400,'Informe a validade no formato de data.');const t=Date.parse(v+'T23:59:59-03:00')/1000;if(!Number.isFinite(t))fail(400,'Data de validade inválida.');if(t<=now())fail(400,'Informe uma data de validade futura.');if(t>now()+5*366*86400)fail(400,'A validade máxima é de cinco anos.');return t;}
function accessSpec(b){if(!b||typeof b!=='object')fail(400,'Dados de acesso inválidos.');return{courseExpires:b.courseExpires?endOfDay(b.courseExpires):null,planner:b.planner===true,fornitore:b.fornitore===true};}
// Ajusta o acesso para o estado pedido: um único registro ativo por produto, mantendo os anteriores como revogados.
async function setAccess(db,userId,spec,actor,source){
 const t=now(),target=spec.courseExpires,current=await all(db,"SELECT * FROM entitlements WHERE user_id=? AND status='active' AND expires>?",userId,t),statements=[],changes=[];
 for(const product of products){
  const wanted=!!target&&(product==='course'||spec[product]===true),rows=current.filter(r=>r.product===product);
  if(wanted?rows.length===1&&rows[0].expires===target&&rows[0].starts<=t:!rows.length)continue;
  for(const r of rows)statements.push(stmt(db,"UPDATE entitlements SET status='revoked',updated=? WHERE id=?",t,r.id));
  if(wanted)statements.push(stmt(db,'INSERT INTO entitlements(id,user_id,product,starts,expires,status,source,reference,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?)',uid(),userId,product,Math.min(t,...rows.map(r=>r.starts)),target,'active',source,actor?.id||null,t,t));
  changes.push(product+':'+(wanted?new Date((target-3*3600)*1000).toISOString().slice(0,10):'removido'));
 }
 if(statements.length&&actor)statements.push(audit(db,actor,'access:'+changes.join(','),userId));
 if(statements.length)await db.batch(statements);
 return changes;
}
