// Materiais da aula. O tipo vem da extensão e é conferido pela assinatura do arquivo quando o formato tem uma.
const lessonFileTypes={pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',odt:'application/vnd.oasis.opendocument.text',ods:'application/vnd.oasis.opendocument.spreadsheet',odp:'application/vnd.oasis.opendocument.presentation',rtf:'application/rtf',txt:'text/plain; charset=utf-8',csv:'text/csv; charset=utf-8',zip:'application/zip',mp3:'audio/mpeg',m4a:'audio/mp4'};
const zipBased=['docx','xlsx','pptx','odt','ods','odp','zip'],oleBased=['doc','xls','ppt'];
const maxLessonFile=25*1024*1024,maxLessonFiles=15;
function lessonFileType(name,bytes){
 const ext=(name.split('.').pop()||'').toLowerCase(),type=lessonFileTypes[ext];if(!type||!name.includes('.'))fail(400,'Formato não permitido. Use PDF, imagens, documentos do Office/LibreOffice, TXT, CSV, ZIP ou MP3.');
 const starts=sig=>sig.every((b,i)=>bytes[i]===b),ascii=s=>[...s].map(c=>c.charCodeAt(0));
 const ok=ext==='pdf'?starts(ascii('%PDF-')):ext==='png'?starts([0x89,0x50,0x4e,0x47]):['jpg','jpeg'].includes(ext)?starts([0xff,0xd8,0xff]):ext==='webp'?starts(ascii('RIFF'))&&String.fromCharCode(...bytes.slice(8,12))==='WEBP':ext==='gif'?starts(ascii('GIF8')):zipBased.includes(ext)?starts([0x50,0x4b,0x03,0x04]):oleBased.includes(ext)?starts([0xd0,0xcf,0x11,0xe0]):ext==='rtf'?starts(ascii('{\\rtf')):ext==='mp3'?starts(ascii('ID3'))||(bytes[0]===0xff&&(bytes[1]&0xe0)===0xe0):true;
 if(!ok)fail(400,'O conteúdo do arquivo não corresponde à extensão .'+ext+'.');
 return type;
}
const filesDir=env=>env.FILES_DIR||nodePath.resolve('data','files');
const inlineTypes=t=>t==='application/pdf'||t.startsWith('image/')||t.startsWith('audio/');
async function lessonFilesOf(db,ids){if(!ids.length)return{};const rows=await all(db,`SELECT id,lesson_id AS lessonId,name,type,size FROM lesson_files WHERE lesson_id IN (${ids.map(()=>'?').join(',')}) ORDER BY position,created`,...ids);const map={};for(const r of rows)(map[r.lessonId]||=[]).push({id:r.id,name:r.name,type:r.type,size:r.size});return map;}

// Vendas. Preços em centavos de real; o curso dá acesso por accessDays dias.
const saleDefaults={coursePrice:99700,plannerPrice:19700,fornitorePrice:29700,renewalDiscount:20,renewalWindowDays:60,accessDays:365};
const renewalLeadDays=60;
const saleNames={course:'Curso Arrivo In Itália (1 ano de acesso)',planner:'Adicional Meu Planner',fornitore:'Adicional Fornitore'};
async function saleSettings(db){const s={...saleDefaults};for(const r of await all(db,"SELECT key,value FROM settings WHERE key LIKE 'sale.%'")){const k=r.key.slice(5);if(k in s)s[k]=Number(r.value);}return s;}
// O que a pessoa pode comprar agora e por quanto. u pode ser nulo (visitante).
async function offerFor(db,u){
 const s=await saleSettings(db),t=now(),prices={course:s.coursePrice,planner:s.plannerPrice,fornitore:s.fornitorePrice};
 if(!u)return{kind:'new',prices,total:prices,discountPercent:0,available:products,activeExtras:[],courseActive:false};
 const a=await accessOf(db,u),last=(await first(db,"SELECT max(expires) AS expires FROM entitlements WHERE user_id=? AND product='course' AND status='active'",u.id))?.expires||null;
 const canRenew=!a.course.active||a.course.expires-t<=renewalLeadDays*86400;
 const discount=last&&canRenew&&s.renewalDiscount>0&&(!s.renewalWindowDays||t<=last+s.renewalWindowDays*86400)?s.renewalDiscount:0;
 const course=Math.round(prices.course*(100-discount)/100);
 const extras=['planner','fornitore'].filter(p=>!a[p].active||canRenew);
 return{kind:last?'renewal':'new',prices,total:{...prices,course},discountPercent:discount,available:[...(canRenew?['course']:[]),...(a.course.active||canRenew?extras:[])],activeExtras:['planner','fornitore'].filter(p=>a[p].active),courseActive:a.course.active,courseExpires:a.course.expires,renewalOpens:a.course.active&&!canRenew?a.course.expires-renewalLeadDays*86400:null};
}
function purchaseProducts(value,offer,addon){
 if(!Array.isArray(value)||!value.length)fail(400,'Escolha o que deseja comprar.');
 const list=[...new Set(value)];if(list.some(p=>!products.includes(p)))fail(400,'Produto inválido.');
 if(!list.includes('course')&&(!addon||!offer.courseActive))fail(400,'Os adicionais são vendidos junto com o curso.');
 if(!list.includes('course')&&offer.activeExtras.some(p=>list.includes(p)))fail(400,'Este adicional já faz parte do seu acesso.');
 for(const p of list)if(!offer.available.includes(p))fail(400,p==='course'?'A renovação fica disponível nos 60 dias anteriores ao vencimento do seu acesso.':'Este adicional já faz parte do seu acesso ou exige o curso ativo.');
 return products.filter(p=>list.includes(p));
}
async function createCheckout(env,db,req,{email,name,userId,kind,items,offer}){
 const id=uid(),origin=new URL(req.url).origin,amounts=items.map(p=>offer.total[p]),amount=amounts.reduce((a,b)=>a+b,0),discount=items.includes('course')?offer.prices.course-offer.total.course:0;
 const session=await stripeRequest(env,'POST','/checkout/sessions',{mode:'payment',locale:'pt-BR',customer_email:email,client_reference_id:id,metadata:{order_id:id},payment_intent_data:{metadata:{order_id:id}},success_url:`${origin}/compra?pedido=${id}&session_id={CHECKOUT_SESSION_ID}`,cancel_url:userId?`${origin}/app#perfil`:`${origin}/#comprar`,line_items:Object.fromEntries(items.map((p,i)=>[i,{quantity:1,price_data:{currency:'brl',unit_amount:amounts[i],product_data:{name:saleNames[p]+(p==='course'&&discount?` (renovação com ${offer.discountPercent}% de desconto)`:'')}}}]))});
 await run(db,'INSERT INTO orders(id,user_id,email,name,kind,products,amount,discount,currency,status,stripe_session,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',id,userId||null,email,name,kind,JSON.stringify(items),amount,discount,'brl','pending',session.id,now(),now());
 return{url:session.url,order:id};
}
// Libera o acesso de um pedido pago. Idempotente: só o primeiro aviso de pagamento tem efeito.
async function fulfillOrder(db,orderId,paymentIntent){
 const t=now(),claim=await run(db,"UPDATE orders SET status='paid',paid_at=?,updated=?,stripe_payment_intent=coalesce(?,stripe_payment_intent) WHERE id=? AND status IN ('pending','failed','expired')",t,t,paymentIntent||null,orderId);
 if(!claim.meta.changes)return;
 const order=await first(db,'SELECT * FROM orders WHERE id=?',orderId);
 try{
  let user=order.user_id?await first(db,'SELECT * FROM users WHERE id=?',order.user_id):await first(db,'SELECT * FROM users WHERE email=?',order.email);const statements=[];
  if(!user){user={id:uid(),email:order.email,name:order.name,role:'student'};statements.push(stmt(db,'INSERT INTO users(id,email,name,password,role,status,created) VALUES(?,?,?,NULL,?,?,?)',user.id,user.email,user.name,'student','active',t));}
  const s=await saleSettings(db),items=JSON.parse(order.products),grant=(product,starts,expires)=>statements.push(stmt(db,'INSERT INTO entitlements(id,user_id,product,starts,expires,status,source,reference,created,updated) VALUES(?,?,?,?,?,?,?,?,?,?)',uid(),user.id,product,starts,expires,'active','stripe',order.id,t,t));
  let start=t,end;
  if(items.includes('course')){const current=(await first(db,"SELECT max(expires) AS expires FROM entitlements WHERE user_id=? AND product='course' AND status='active' AND expires>?",user.id,t))?.expires;start=Math.max(t,current||0);end=start+s.accessDays*86400;grant('course',start,end);}
  else{end=(await accessOf(db,user)).course.expires;if(!end)throw new Error('Adicional pago sem curso ativo.');}
  for(const p of items.filter(p=>p!=='course'))grant(p,items.includes('course')?start:t,end);
  statements.push(stmt(db,'UPDATE orders SET user_id=? WHERE id=?',user.id,order.id));
  await db.batch(statements);
 }catch(e){await run(db,"UPDATE orders SET status='pending',paid_at=NULL WHERE id=?",orderId);throw e;}
}
async function syncOrder(env,db,order){
 if(order.status!=='pending'||!order.stripe_session||!env.STRIPE_SECRET_KEY)return order;
 const session=await stripeRequest(env,'GET','/checkout/sessions/'+encodeURIComponent(order.stripe_session));
 if(session.payment_status==='paid'){await fulfillOrder(db,order.id,session.payment_intent);return first(db,'SELECT * FROM orders WHERE id=?',order.id);}
 return order;
}
// Link para o comprador criar a senha. Gerado sob demanda; tokens anteriores do mesmo tipo deixam de valer.
async function welcomeLink(db,req,email){const raw=token();await db.batch([stmt(db,"UPDATE invites SET used=1 WHERE email=? AND kind='welcome'",email),stmt(db,'INSERT INTO invites(token,email,role,kind,expires,used) VALUES(?,?,?,?,?,0)',await hash(raw),email,'student','welcome',now()+7*86400)]);return new URL(req.url).origin+'/app#ativar?token='+raw;}
async function stripeWebhook(req,env){
 const db=env.DB,raw=await req.text();if(raw.length>1000000)fail(413,'Conteúdo muito grande.');
 if(!await verifyWebhook(env,raw,req.headers.get('stripe-signature')))fail(400,'Assinatura inválida.');
 const event=JSON.parse(raw),object=event.data?.object||{},orderId=object.metadata?.order_id||object.client_reference_id;
 if(event.type.startsWith('checkout.session.')){
  const order=orderId&&await first(db,'SELECT * FROM orders WHERE id=? AND stripe_session=?',orderId,object.id);
  if(!order)return json({received:true,ignored:true});
  if(['checkout.session.completed','checkout.session.async_payment_succeeded'].includes(event.type)&&object.payment_status==='paid')await fulfillOrder(db,order.id,object.payment_intent);
  else if(event.type==='checkout.session.completed')await run(db,'UPDATE orders SET stripe_payment_intent=?,updated=? WHERE id=?',object.payment_intent||null,now(),order.id);
  else if(event.type==='checkout.session.async_payment_failed')await run(db,"UPDATE orders SET status='failed',updated=? WHERE id=? AND status='pending'",now(),order.id);
  else if(event.type==='checkout.session.expired')await run(db,"UPDATE orders SET status='expired',updated=? WHERE id=? AND status='pending'",now(),order.id);
 }
 if(event.type==='charge.refunded'&&object.payment_intent){
  const order=await first(db,"SELECT * FROM orders WHERE stripe_payment_intent=? AND status='paid'",object.payment_intent);
  if(order&&object.amount_refunded>=object.amount)await db.batch([stmt(db,"UPDATE orders SET status='refunded',updated=? WHERE id=?",now(),order.id),stmt(db,"UPDATE entitlements SET status='revoked',updated=? WHERE reference=? AND source='stripe'",now(),order.id)]);
 }
 return json({received:true});
}
