async function upsertDraft(db,content,authorId){const t=now(),d=await first(db,"SELECT id FROM sales_page_versions WHERE status='draft'");await(d?run(db,'UPDATE sales_page_versions SET content=?,author_id=?,updated=? WHERE id=?',JSON.stringify(content),authorId,t,d.id):run(db,'INSERT INTO sales_page_versions(id,status,content,author_id,created,updated) VALUES(?,?,?,?,?,?)',uid(),'draft',JSON.stringify(content),authorId,t,t));return t;}
// Aceita "1.297,90", "1297,90" e "1297.90".
const reais=v=>{const s=String(v).trim().replace(/^R\$\s*/,''),n=Number(s.includes(',')?s.replace(/\./g,'').replace(',','.'):s);if(!Number.isFinite(n)||n<1||n>100000)fail(400,'Informe preços entre R$ 1 e R$ 100.000.');return Math.round(n*100);};

function validateTrackImage(value){
 if(value===undefined||value==='')return '';
 if(typeof value!=='string'||value.length>683000)fail(400,'A imagem deve ter até 500 KB.');
 const match=/^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);
 if(!match)fail(400,'Use uma imagem JPG, PNG ou WebP.');
 let bytes;try{bytes=atob(match[2]);}catch{fail(400,'Imagem inválida.');}
 if(bytes.length>512000)fail(400,'A imagem deve ter até 500 KB.');
 const valid=match[1]==='png'?bytes.startsWith('\x89PNG\r\n\x1a\n'):match[1]==='jpeg'?bytes.startsWith('\xff\xd8\xff'):bytes.startsWith('RIFF')&&bytes.slice(8,12)==='WEBP';
 if(!valid)fail(400,'Arquivo de imagem inválido.');return value;
}


// Tarefas do planner de uma trilha: as do modelo publicado em Gestão do Planner ou, sem modelo, uma por módulo da trilha.
async function plannerTasks(db,trackRow){const template=await first(db,"SELECT body FROM records WHERE kind='planner' AND status='published' AND json_extract(body,'$.trackId')=?",trackRow.id);if(template)return JSON.parse(template.body).items.map(i=>({id:i.id,title:i.title,phase:i.phase}));const track=JSON.parse(trackRow.body);return track.groups.flatMap(([phase,ids])=>ids.map(id=>({id,phase})));}
async function plannerTarget(db,trackId,itemId){const row=await first(db,"SELECT * FROM records WHERE id=? AND kind='track' AND status='published'",trackId);if(!row)fail(400,'Trilha indisponível.');if(!(await plannerTasks(db,row)).some(t=>t.id===itemId))fail(400,'Etapa indisponível.');return row;}
function attachmentData(value){if(typeof value!=='string'||value.length>2800000)fail(400,'O arquivo deve ter até 2 MB.');const match=/^data:(application\/pdf|image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);if(!match)fail(400,'Envie um arquivo PDF, JPG, PNG ou WebP.');let bytes;try{bytes=atob(match[2]);}catch{fail(400,'Arquivo inválido.');}if(bytes.length>2097152)fail(400,'O arquivo deve ter até 2 MB.');const valid=match[1]==='application/pdf'?bytes.startsWith('%PDF-'):match[1]==='image/png'?bytes.startsWith('\x89PNG\r\n\x1a\n'):match[1]==='image/jpeg'?bytes.startsWith('\xff\xd8\xff'):bytes.startsWith('RIFF')&&bytes.slice(8,12)==='WEBP';if(!valid)fail(400,'O conteúdo do arquivo não corresponde ao formato informado.');return{type:match[1],data:match[2],size:bytes.length};}
function attachmentResponse(row,download=false){const binary=atob(row.data),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const fallback=row.type==='application/pdf'?'documento.pdf':row.type==='image/png'?'imagem.png':row.type==='image/webp'?'imagem.webp':'imagem.jpg',name=(row.name||fallback).replace(/[\r\n"\\/]/g,'_');return new Response(bytes,{headers:{'Content-Type':row.type,'Content-Length':String(row.size),'Content-Disposition':`${download?'attachment':'inline'}; filename="${name}"`,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});}
async function validatePlanner(db,trackId,value){

 const row=await first(db,"SELECT * FROM records WHERE id=? AND kind='track' AND status='published'",trackId);if(!row)fail(400,'Trilha indisponível.');
 if(!value||typeof value!=='object'||Array.isArray(value)||!Array.isArray(value.items)||value.items.length>100)fail(400,'Planner inválido.');
 const allowed=new Set((await plannerTasks(db,row)).map(t=>t.id));if(value.items.length!==new Set(value.items.map(i=>i.id)).size)fail(400,'Etapas duplicadas.');
 const statuses=new Set(['not_started','organizing','waiting','in_progress','blocked','done']),priorities=new Set(['low','normal','high']),currencies=new Set(['EUR','BRL']);
 const clean=[];for(const item of value.items){const id=text(item.id,1,100);if(!allowed.has(id))fail(400,'Etapa indisponível.');const status=statuses.has(item.status)?item.status:'not_started',priority=priorities.has(item.priority)?item.priority:'normal',currency=currencies.has(item.currency)?item.currency:'EUR';const dateValue=v=>{if(!v)return '';if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v)))fail(400,'Data inválida.');return v;};const cost=item.cost===''||item.cost==null?'':Number(item.cost);if(cost!==''&&(!Number.isFinite(cost)||cost<0||cost>9999999))fail(400,'Custo inválido.');clean.push({id,title:text(item.title||'',0,160),phase:text(item.phase||'',0,160),status,responsible:text(item.responsible||'',0,120),issuanceDate:dateValue(item.issuanceDate),dueDate:dateValue(item.dueDate),cost,currency,priority,documentNumber:text(item.documentNumber||'',0,120),location:text(item.location||'',0,160),attachmentName:text(item.attachmentName||'',0,160),attachmentUrl:urlValue(item.attachmentUrl||''),notes:text(item.notes||'',0,5000),updated:Number.isFinite(Number(item.updated))?Number(item.updated):now()*1000});}
 return{trackId,items:clean,updated:now()*1000};
}
async function validateRecord(db,kind,b,status,id){const base={title:text(b.title,1,160),description:text(b.description||'',0,10000),order:Number.isInteger(Number(b.order))?Number(b.order):0};if(base.order<0||base.order>10000)fail(400,'Ordem inválida.');if(kind==='category')return{...base,showOnHome:b.showOnHome!==false};
 if(kind==='module'){const cardStyle=b.cardStyle==='image'?'image':'symbol',cardImage=validateTrackImage(b.cardImage);if(cardStyle==='image'&&!cardImage)fail(400,'Envie a imagem do cartão ou escolha exibir um símbolo.');const categoryId=text(b.categoryId||'',1,100),cat=await first(db,"SELECT body FROM records WHERE id=? AND kind='category' AND status<>'archived'",categoryId);if(!cat)fail(400,'Escolha uma categoria ativa para o módulo.');return{...base,categoryId,category:JSON.parse(cat.body).title,symbol:text(b.symbol||'◇',1,8),cardStyle,cardImage};}
 if(kind==='lesson'){const moduleId=text(b.moduleId,1,100);const m=await first(db,'SELECT id FROM records WHERE id=? AND kind=? AND status<>?',moduleId,'module','archived');if(!m)fail(400,'Selecione um módulo ativo.');const video=videoSource(b.videoUrl||'');if(status==='published'&&!video)fail(400,'Insira o vídeo antes de publicar a aula.');const tasks=Array.isArray(b.tasks)?b.tasks.map(t=>({id:text(t.id||uid(),1,100),title:text(t.title,1,300)})):[];if(tasks.length>30||new Set(tasks.map(t=>t.id)).size!==tasks.length)fail(400,'Tarefas inválidas.');
  const links=Array.isArray(b.links)?b.links.filter(x=>x&&(x.title||x.url)).map(x=>({title:text(x.title||'',1,160),url:linkValue(x.url)})):[];if(links.length>20)fail(400,'Use no máximo 20 links por aula.');
  const plannerLinks=[];for(const x of Array.isArray(b.plannerTasks)?b.plannerTasks:[]){const trackId=text(x?.trackId||'',1,100),itemId=text(x?.itemId||'',1,100);const track=await first(db,"SELECT * FROM records WHERE id=? AND kind='track' AND status<>'archived'",trackId);if(!track||!(await plannerTasks(db,track)).some(t=>t.id===itemId))fail(400,'Uma das tarefas do planner não está mais disponível.');if(!plannerLinks.some(p=>p.trackId===trackId&&p.itemId===itemId))plannerLinks.push({trackId,itemId});}if(plannerLinks.length>10)fail(400,'Vincule no máximo 10 tarefas do planner.');
  return{...base,moduleId,videoUrl:urlValue(b.videoUrl||''),video,...lessonDuration(b),tasks,links,plannerTasks:plannerLinks};}
 if(kind==='track'){if(!Array.isArray(b.groups)||b.groups.length>25)fail(400,'Organize as etapas da trilha.');const groups=[];for(const g of b.groups){if(!Array.isArray(g)||!Array.isArray(g[1])||g[1].length>30)fail(400,'Etapa inválida.');const ids=[...new Set(g[1])];for(const mid of ids){if(typeof mid!=='string'||!await first(db,'SELECT id FROM records WHERE id=? AND kind=? AND status<>?',mid,'module','archived'))fail(400,'A etapa contém um módulo indisponível.');}groups.push([text(g[0],1,160),ids]);}if(status==='published'&&(!groups.length||!groups.some(g=>g[1].length)))fail(400,'Adicione módulos antes de publicar a trilha.');return{...base,backgroundImage:validateTrackImage(b.backgroundImage),name:base.title,tag:text(b.tag||'SUA JORNADA',0,100),groups};}
 if(kind==='provider'){const price=Number(b.price),duration=Number(b.duration);if(!Number.isFinite(price)||price<0||price>9999999)fail(400,'Preço inválido.');if(!Number.isInteger(duration)||duration<15||duration>480)fail(400,'Duração inválida.');return{...base,name:base.title,brand:text(b.brand||'',0,120),specialty:text(b.specialty,2,120),services:text(b.services||'',0,2000),summary:text(b.summary||'',0,500),bio:text(b.bio||'',0,10000),photo:validateTrackImage(b.photo),price,currency:b.currency==='BRL'?'BRL':'EUR',duration,rating:Math.max(0,Math.min(5,Number(b.rating)||0)),reviewCount:Math.max(0,Math.min(999999,Number(b.reviewCount)||0)),city:text(b.city||'',0,120),languages:text(b.languages||'',0,300),email:email(b.email),phone:text(b.phone||'',0,60),website:urlValue(b.website||''),credentials:text(b.credentials||'',0,3000),availability:text(b.availability||'',0,2000),featured:b.featured===true};}
 if(kind==='planner'){const trackId=text(b.trackId,1,100);if(!await first(db,"SELECT id FROM records WHERE id=? AND kind='track' AND status<>?",trackId,'archived'))fail(400,'Selecione uma trilha ativa.');if(!Array.isArray(b.items)||b.items.length>100)fail(400,'Configure as tarefas do planner.');const priorities=new Set(['low','normal','high']),currencies=new Set(['EUR','BRL']),items=[];for(const raw of b.items){const cost=raw.estimatedCost===''?'':Number(raw.estimatedCost),dueDays=raw.dueDays===''?'':Number(raw.dueDays);if(cost!==''&&(!Number.isFinite(cost)||cost<0||cost>9999999))fail(400,'Custo estimado inválido.');if(dueDays!==''&&(!Number.isInteger(dueDays)||dueDays<0||dueDays>3650))fail(400,'Prazo estimado inválido.');items.push({id:text(raw.id||uid(),1,100),title:text(raw.title,2,160),phase:text(raw.phase,2,160),description:text(raw.description||'',0,2000),responsibleHint:text(raw.responsibleHint||'',0,120),priority:priorities.has(raw.priority)?raw.priority:'normal',estimatedCost:cost,currency:currencies.has(raw.currency)?raw.currency:'EUR',dueDays,requiredDocuments:text(raw.requiredDocuments||'',0,2000),attachmentRequired:raw.attachmentRequired===true,order:Number.isInteger(Number(raw.order))?Math.max(0,Math.min(10000,Number(raw.order))):items.length});}if(new Set(items.map(i=>i.id)).size!==items.length)fail(400,'Existem tarefas duplicadas.');return{...base,trackId,items:items.sort((a,b)=>a.order-b.order)};}
 if(kind==='event'){const start=Date.parse(b.start),end=Date.parse(b.end);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)fail(400,'Informe início e término válidos.');return{...base,start:new Date(start).toISOString(),end:new Date(end).toISOString(),host:text(b.host||'',0,160),location:text(b.location||'',0,300),joinUrl:urlValue(b.joinUrl||'')};}fail(400,'Tipo de conteúdo inválido.');}

